typedef unsigned int big_int;

class stringx;

class string_buf
{
  big_int *data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;

public:
  int compare(const char *str) const
  {
    int i;
    const char *a = reinterpret_cast<const char *>(data);
    for (i = 0; i < char_length; i++)
    {
      if (str[i] == '\0') return -1;
      if (a[i] == str[i]) continue;
      if (str[i] > a[i]) return 1;
      if (str[i] < a[i]) return -1;
    }
    if (str[i] == '\0') return 0;
    return 1;
  }

  bool is_equal(const char *str) const
  {
    return (compare(str) == 0);
  }

  friend class stringx;
  friend stringx operator+(const char *, const stringx &);
  friend stringx operator+(const stringx &, const char *);
};

class stringx
{
  char *chars;
  string_buf *my_buf;

public:
  stringx();
  stringx(const stringx &);
  ~stringx();
  void make_room(int);
  void append(const char *, int = -1);
  void append(const stringx &);
  const char *c_str() const { return chars; }

  friend bool operator==(const stringx &lhs, const char *rhs);
  friend stringx operator+(const char *lhs, const stringx &rhs);
  friend stringx operator+(const stringx &lhs, const char *rhs);
};

extern "C" int strlen(const char *);

inline bool operator==(const stringx &lhs, const char *rhs)
{
  return lhs.my_buf->is_equal(rhs);
}

inline stringx operator+(const char *lhs, const stringx &rhs)
{
  stringx foo;
  int len = strlen(lhs);

  foo.make_room(len + rhs.my_buf->char_length);
  foo.append(lhs, len);
  foo.append(rhs);

  return foo;
}

inline stringx operator+(const stringx &lhs, const char *rhs)
{
  stringx foo;
  int len = strlen(rhs);

  foo.make_room(len + lhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs, len);

  return foo;
}

class entity;

class entity_id
{
public:
  entity_id(const char *name);

private:
  unsigned int val;
};

enum entity_flavor_t
{
  ENTITY_CAMERA,
  ENTITY_ENTITY,
  ENTITY_MARKER,
  ENTITY_MIC,
  ENTITY_LIGHT_SOURCE,
  ENTITY_PARTICLE_GENERATOR,
  ENTITY_PHYSICAL,
  ENTITY_ITEM,
  ENTITY_LIGHT,
  ENTITY_MOBILE,
  ENTITY_CONGLOMERATE,
  ENTITY_TURRET,
  ENTITY_BEAM,
  ENTITY_SCANNER,
  ENTITY_MORPHABLE_ITEM,
  ENTITY_SKY,
  ENTITY_MANIP,
  ENTITY_SWITCH,
  ENTITY_BOX_TRIGGER,
  ENTITY_POLYTUBE,
  ENTITY_LENSFLARE,
  NUM_ENTITY_FLAVORS,
  IGNORE_FLAVOR
};

class entity_manager
{
public:
  static entity_manager *inst();
  entity *find_entity(const entity_id &, entity_flavor_t, bool);
};

void error(const stringx &);

enum
{
  FIND_ENTITY_UNKNOWN_NOT_OK = false,
  FIND_ENTITY_UNKNOWN_OK = true
};

class slc_entity_t
{
public:
  virtual unsigned find_instance(const stringx &n) const;
};

unsigned slc_entity_t::find_instance(const stringx& n) const
{
  if (n=="NULL") return (unsigned)0;
  const entity* r = entity_manager::inst()->find_entity(entity_id(n.c_str()),IGNORE_FLAVOR,FIND_ENTITY_UNKNOWN_OK);
  if (!r)
    {
    error( "entity " + n + " not found" );
    }
  return (unsigned)r;
}
